/**
 * @event
 * @name scwin.btn_mpd_files_del_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); } 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11010.btn_mpd_files_del_onclick' }); }
};

/**
 * @event
 * @name scwin.attachFileList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.attachFileList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try { if (columnId === 'attachFileNm') { var __d = $c.util.getComponent('dlt_attachFileList'); if (!__d) { return; } if (typeof scwin.fileDown === 'function') { await scwin.fileDown(String(__d.getCellData(rowIndex, "disclsConsultApplId")), String(__d.getCellData(rowIndex, "seq"))); } else { console.error('[sdd] 행 동작 미정의: scwin.fileDown (열 attachFileNm)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fileDown'); } return; } if (columnId === '_del') { var __d = $c.util.getComponent('dlt_attachFileList'); if (!__d) { return; } if (typeof scwin.fn_fileDel === 'function') { scwin.fn_fileDel(String(__d.getCellData(rowIndex, "disclsConsultApplId")), String(__d.getCellData(rowIndex, "seq")), String(__d.getCellData(rowIndex, "attachFileNm")), rowIndex); } else { console.error('[sdd] 행 동작 미정의: scwin.fn_fileDel (열 _del)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fn_fileDel'); } return; } 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11010.attachFileList_oncellclick' }); }
};

