        if ($c.util.getComponent('ipt_directSelected').getValue() === 'Y' && dma_hiddenStore.get("ipt_disclsConsultApplId") !== '') {
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('wrtrNmTemp', ($c.util.getComponent("ipt_wrtrNm").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: wrtrNmTemp'));
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('telNoTemp', ($c.util.getComponent("ipt_telNo").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: telNoTemp'));
