/**
 * @method
 * @name scwin.calBytes
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.calBytes = function (str) {
    /* sdd-asis-lifecycle:begin fn_calBytes — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validation
 * @author Inswave
 * @date 2026. 09. 29
 * @param sec
 * @returns
 * @hidden N
*/
scwin.validation = async function (sec) {
    /* sdd-asis-lifecycle:begin fn_validation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (sec === 'temp') {
        var disclsChrg = $('#disclsChrg option:selected').val();
        if (disclsChrg === 'direct') {
            if (dma_hiddenStore.get("telNoTemp") !== '' && dma_hiddenStore.get("telNoTemp") != null) {
                if (scwin.fnTelNoCheck(dma_hiddenStore.get("telNoTemp"))) {
                    await $c.win.alert("연락처 형식이 틀렸습니다.\nex)02-0000-0000");
                    return false;
                }
            }
            if (dma_hiddenStore.get("cellphoneNoTemp") !== '' && dma_hiddenStore.get("cellphoneNoTemp") != null) {
                if (scwin.fnCellPhoneCheck(dma_hiddenStore.get("cellphoneNoTemp"))) {
                    await $c.win.alert("휴대폰 형식이 틀렸습니다.\nex)010-0000-0000");
                    return false;
                }
            }
        }
        if ($c.util.getComponent('ipt_formKorNm').getValue().trim() === '' || $c.util.getComponent('ipt_formKorNm').getValue() == null) {
            await $c.win.alert("제목을 입력하세요.");
            return false;
        }
        if (($c.util.getComponent('txa_quesContn').getValue() == null ? '' : String($c.util.getComponent('txa_quesContn').getValue())) !== '' && $c.util.getComponent('txa_quesContn').getValue() != null) {
            if (scwin.calBytes($c.util.getComponent('txa_quesContn').getValue()) > 2000) {
                await $c.win.alert("상담내용은 한글 1000자 이하, 숫자/영문 2000자 이하까지만 입력이 가능합니다.");
                return false;
            }
        }
    } else {
        var disclsChrg = $('#disclsChrg option:selected').val();
        if (disclsChrg === 'direct') {
            if (dma_hiddenStore.get("wrtrNmTemp") === '' || dma_hiddenStore.get("wrtrNmTemp") == null) {
                await $c.win.alert("등록자를 작성하세요.");
                return false;
            }
            if ((dma_hiddenStore.get("telNoTemp") === '' || dma_hiddenStore.get("telNoTemp") == null) && (dma_hiddenStore.get("cellphoneNoTemp") === '' || dma_hiddenStore.get("cellphoneNoTemp") == null)) {
                await $c.win.alert("연락처 또는 휴대폰을 작성하세요.");
                return false;
            }
            if (dma_hiddenStore.get("telNoTemp") !== '' && scwin.fnTelNoCheck(dma_hiddenStore.get("telNoTemp"))) {
                await $c.win.alert("연락처 형식이 틀렸습니다.\nex)02-0000-0000");
                return false;
            }
            if (dma_hiddenStore.get("cellphoneNoTemp") !== '' && scwin.fnCellPhoneCheck(dma_hiddenStore.get("cellphoneNoTemp"))) {
                await $c.win.alert("휴대폰 형식이 틀렸습니다.\nex)010-0000-0000");
                return false;
            }
        }
        if (($c.util.getComponent('cal_disclsSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_disclsSchdlDd').getValue())) === '' || $c.util.getComponent('cal_disclsSchdlDd').getValue() == null) {
            await $c.win.alert("공시예정일을 선택하세요.");
            return false;
        }
        if (($c.util.getComponent('ipt_formKorNm').getValue() == null ? '' : String($c.util.getComponent('ipt_formKorNm').getValue())) === '' || $c.util.getComponent('ipt_formKorNm').getValue() == null) {
            await $c.win.alert("제목을 입력하세요.");
            return false;
        }
