/**
 * @method
 * @name scwin.fnTelNoCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_telNo
 * @returns
 * @hidden N
*/
scwin.fnTelNoCheck = function (ipt_telNo) {
    /* sdd-asis-lifecycle:begin fnTelNoCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const regTelNo = /^(0[2-8][0-5]?)-?([1-9]{1}[0-9]{2,3})-?([0-9]{4})$/;
    if (!regTelNo.test(ipt_telNo)) {
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnCellPhoneCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param cellPhoneNum
 * @returns
 * @hidden N
*/
scwin.fnCellPhoneCheck = function (cellPhoneNum) {
    /* sdd-asis-lifecycle:begin fnCellPhoneCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const regPhone = /(01[0|1|6|7|8|9])[-](\d{3}|\d{4})[-](\d{4}$)/g;
    if (!regPhone.test(cellPhoneNum)) {
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileValidation
 * @author Inswave
 * @date 2026. 09. 29
 * @param sec
 * @returns
 * @hidden N
*/
scwin.fileValidation = async function (sec) {
    /* sdd-asis-lifecycle:begin fn_fileValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const file = $("input[type='file']");
    let fCnt = 0;
    let fNmLength = 0;
    let fType = 0;
    let fSize = 0;
    for (let i = 0; i < file.length; i++) {
        if (file.eq(i).attr("value") !== '' && file.eq(i).attr("value") != null) {
            fCnt++;
            fNmLength += scwin.fileNmLengthChk(file.eq(i).attr("value"));
            fType += scwin.fileTypeChk(file.eq(i).attr("value"));
            fSize += scwin.fileSizeChk($c.util.getComponent("attachFile" + (i + 1)).files[0].size);
        }
    }
    if (fNmLength > 0) {
        await $c.win.alert('파일명 길이가 80byte 초과된 파일이 ' + fNmLength + '개 있습니다.');
        return false;
    }
    if (fType > 0) {
        await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 ' + fType + '개 있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
        return false;
    }
    if (fSize > 0) {
        await $c.win.alert('첨부파일의 용량은 개당 50MB를 넘을수 없습니다.');
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileTypeChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.fileTypeChk = function (val) {
    /* sdd-asis-lifecycle:begin fn_fileTypeChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isFileType = new Array("drt", "bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt");
    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
    let returnVal = 0;
    let typeChkCnt = 0;
    for (i = 0; i < isFileType.length; i++) {
        if (isFileType[i] === fileType) {
            typeChkCnt++;
        }
    }
    if (typeChkCnt == 0) {
        returnVal = 1;
    }
    return returnVal;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
