/**
 * @method
 * @name scwin.apiFileUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.apiFileUpload = async function () {
    /* sdd-asis-lifecycle:begin fn_apiFileUpload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let bl = false;
    let mimeError = true;
    const all_files = $('[type=file]');
    if (all_files.length > 0) {
        $.each(all_files, function(i, item) {
                const f = $(item)[0].files[0];
                if (f == null || f === '') {
                    let idNum = $(item)[0].id;
                    idNum = idNum.replace('attachFile', '');
                    $('#fileDiv' + idNum).remove();
                }
        });
    } else {
        return true;
    }
    const oData = await scwin.getOtherData();
    if (oData === '' || oData == null || oData === 'undefined') {
        void('apiKey 조회에 실패');
        return bl;
    }
    const arr = oData.split('||');
    const apiUrl = scwin.urlInfo();
    const attach_files = $('[type=file]');
    let errCnt = attach_files.length;
    if (attach_files.length > 0) {
        $.each(attach_files, function(i, item) {
                const formData = new FormData();
                formData.append("attachFile", $(item)[0].files[0]);
                formData.append("integUsrId", arr[1]);
                const disclsConsultApplId = dma_hiddenStore.get("ipt_disclsConsultApplId");
                $.ajax({ url: apiUrl + "/auth/s1/disclosure/consult-apply/file-upload/" + disclsConsultApplId, type: "POST", data: formData, processData: false, contentType: false, async: false, headers: { "apiKey": arr[0] }, success: function(response) {
                            void('success : ' + response);
                            errCnt--;
                        }, error: function(request) {
                            void('error : ' + request);
                            errCnt++;
                            mimeError = false;
                        } });
        });
    }
    if (!mimeError) {
        bl = "E";
    } else {
        if (errCnt == 0) {
            bl = true;
        } else {
            bl = false;
        }
    }
    return bl;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
