/**
 * @method
 * @name scwin.fileUploadDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fileUploadDone = async function (data) {
    /* sdd-asis-lifecycle:begin fn_fileUpload_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    if (scwin.result.returnVal === 'Y') {
        bl = true;
    } else {
        if (scwin.result.returnVal === 'E') {
            await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
            bl = "E";
        } else {
            bl = false;
        }
    }
    /* sdd-asis-lifecycle:end */
};

